WITH cleaned AS (SELECT id, customer_id, device, started_at, country, CASE WHEN browser = 'Chrome' THEN 1 ELSE 0 END AS is_chrome, COALESCE(country, 'NONE') AS resolved_country FROM sessions WHERE started_at >= TO_TIMESTAMP('2023-06-29 03:00:00')), enriched AS (SELECT id, customer_id, device, country, resolved_country, AVG(is_chrome) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS is_chrome_avg_2_prior, LAST_VALUE(is_chrome, TRUE) OVER w_running AS last_known_is_chrome, COUNT(is_chrome) OVER (PARTITION BY customer_id ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS is_chrome_count_7d FROM cleaned WINDOW w_running AS (PARTITION BY country ORDER BY is_chrome, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), kept AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.page IN ('/product', '/search'))), deduped AS (SELECT * FROM kept QUALIFY ROW_NUMBER() OVER (PARTITION BY country ORDER BY is_chrome_count_7d DESC NULLS FIRST, id) = 1), grouped AS (SELECT country, MAX(last_known_is_chrome) FILTER (WHERE device = 'desktop') AS desktop_max_last_known_is_chrome, ROUND(SUM(is_chrome_count_7d) / NULLIF(COUNT(CASE WHEN country = 'SG' THEN 1 END), 0), 2) AS is_chrome_count_7d_per_sg FROM deduped GROUP BY country) SELECT country FROM grouped;
